  "claim": {
    "component_id": "C059.component",
    "value": "If the required workload stability and observation time for apparent settling are not both present, the description should be limited to the observed transient.",
    "scope": "Conditional reporting restriction when settling prerequisites are unmet.",
    "provenance": {
      "refs": [
        {
          "source_id": "P038",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly supplies both prerequisites and the restriction when they are not jointly satisfied."
    }
  },
  "signal_basis": {
    "component_id": "C059.signal_basis",
    "value": "The trajectory following a controlled concurrency reduction exhibits temporal changes or apparent settling, but sufficient workload stability or observation time is absent.",
    "scope": "Hypothetical observation under the proposed test, restricted to the recorded transient when settling prerequisites are unmet.",
    "provenance": {
      "refs": [
